43	                                    HttpServletResponse response,
44	                                    FilterChain filterChain) throws ServletException, IOException {
45	        try {
46	            String actorId = request.getHeader(HEADER_ACTOR);
47	            String roleHeader = request.getHeader(HEADER_ROLE);
48	            if (actorId == null || actorId.isBlank() || roleHeader == null || roleHeader.isBlank()) {
49	                writeError(response, HttpServletResponse.SC_UNAUTHORIZED, "缺少 X-Actor-Id 或 X-Role 请求头");
50	                return;
51	            }
52	            if (actorId.trim().length() > 64) {
53	                writeError(response, HttpServletResponse.SC_BAD_REQUEST, "X-Actor-Id 长度不能超过 64 个字符");
54	                return;
