71	        response.setStatus(status);
72	        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
73	        response.setCharacterEncoding("UTF-8");
74	        objectMapper.writeValue(response.getWriter(),
75	                Map.of("error", "UNAUTHORIZED", "message", message));
76	    }
