34	            h.set("X-Actor-Id", actor);
35	        }
36	        if (role != null) {
37	            h.set("X-Role", role);
38	        }
39	        if (requestId != null) {
40	            h.set("X-Request-Id", requestId);
41	        }
42	        h.setContentType(MediaType.APPLICATION_JSON);
43	        return h;
44	    }
