46	    private ResponseEntity<String> post(String path, HttpHeaders headers, String body) {
47	        return rest.exchange(path, HttpMethod.POST, new HttpEntity<>(body, headers), String.class);
48	    }
49	
50	    private JsonNode json(ResponseEntity<String> response) throws Exception {
51	        assertNotNull(response.getBody());
52	        return mapper.readTree(response.getBody());
53	    }
54	
55	    @Test
56	    void replaySameKeySameParams_returnsOriginalResult_andNoDuplicateBusinessRow() throws Exception {
57	        ResponseEntity<String> first = post("/api/experiments/IDEM-1",
58	                headers("c1", "COORDINATOR", "idem-key-1"), "{\"blockCount\":3}");
59	        assertEquals(201, first.getStatusCode().value());
60	        JsonNode firstBody = json(first);
61	        assertEquals(3, firstBody.path("blockCount").asInt());
62	
63	        // 同键同参同操作者重放：原结果（201 与相同响应体），不产生第二个实验
64	        ResponseEntity<String> replay = post("/api/experiments/IDEM-1",
65	                headers("c1", "COORDINATOR", "idem-key-1"), "{\"blockCount\":3}");
66	        assertEquals(201, replay.getStatusCode().value());
67	        assertEquals(first.getBody(), replay.getBody());
68	
69	        // 不带 requestId 的同业务请求会命中“实验已存在”409，证明重放不是重新执行业务
70	        ResponseEntity<String> noIdem = post("/api/experiments/IDEM-1",
71	                headers("c1", "COORDINATOR", "idem-key-other"), "{\"blockCount\":3}");
72	        assertEquals(409, noIdem.getStatusCode().value());
