75	                "SELECT COUNT(*) FROM experiment WHERE id = 'IDEM-1'", Integer.class));
76	        assertEquals(1, jdbc.queryForObject(
77	                "SELECT COUNT(*) FROM idempotent_request WHERE request_id = 'idem-key-1'",
78	                Integer.class));
