81	    @Test
82	    void sameKeyDifferentParamsOrActor_conflicts() {
83	        assertEquals(201, post("/api/experiments/IDEM-2",
84	                headers("c1", "COORDINATOR", "idem-key-2"), "{\"blockCount\":2}")
85	                .getStatusCode().value());
86	
87	        // 异参（不同 blockCount）：409
88	        assertEquals(409, post("/api/experiments/IDEM-2",
89	                headers("c1", "COORDINATOR", "idem-key-2"), "{\"blockCount\":4}")
90	                .getStatusCode().value());
91	
92	        // 异操作者：409
93	        assertEquals(409, post("/api/experiments/IDEM-2",
94	                headers("c2", "COORDINATOR", "idem-key-2"), "{\"blockCount\":2}")
95	                .getStatusCode().value());
96	
97	        // 异角色（同一 actorId 换 REVIEWER）：权限校验先于幂等回放，直接 403
98	        assertEquals(403, post("/api/experiments/IDEM-2",
99	                headers("c1", "REVIEWER", "idem-key-2"), "{\"blockCount\":2}")
100	                .getStatusCode().value());
101	    }
102	
103	    @Test
104	    void failedRequest_doesNotConsumeKey() {
105	        // 非法 blockCount：400，失败不占键
106	        ResponseEntity<String> failed = post("/api/experiments/IDEM-3",
107	                headers("c1", "COORDINATOR", "idem-key-3"), "{\"blockCount\":1}");
108	        assertEquals(400, failed.getStatusCode().value());
109	        assertEquals(0, jdbc.queryForObject(
110	                "SELECT COUNT(*) FROM idempotent_request WHERE request_id = 'idem-key-3'",
111	                Integer.class));
112	
113	        // 同一 requestId 换成合法参数：成功，证明失败未占键
114	        ResponseEntity<String> success = post("/api/experiments/IDEM-3",
115	                headers("c1", "COORDINATOR", "idem-key-3"), "{\"blockCount\":2}");
116	        assertEquals(201, success.getStatusCode().value());
117	
